import Foundation
import Testing

/// A golden test vector file generated by `tools/test-vectors` (`make vectors`).
struct VectorFile<Input: Decodable & Sendable, Expected: Decodable & Sendable>: Decodable, Sendable {
    struct Vector: Decodable, Sendable, CustomTestStringConvertible {
        let name: String
        let input: Input
        let expected: Expected

        var testDescription: String { name }
    }

    let generator: String
    let source: String
    let vectors: [Vector]

    /// Loads `Vectors/<name>.json` from the test bundle.
    static func load(_ name: String) throws -> [Vector] {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Vectors"))
        return try JSONDecoder().decode(Self.self, from: Data(contentsOf: url)).vectors
    }
}

extension [UInt8] {
    /// Decodes a lowercase hex string as used in the vector files.
    init(hex: String) throws {
        var bytes: [UInt8] = []
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            bytes.append(try #require(UInt8(hex[index..<next], radix: 16)))
            index = next
        }
        self = bytes
    }
}
